import sys; sys.path.insert(0,'/home/claude/honglifecalc/build')
from enrich_lib import build, table, faq_html
calc='''function calc(){const h=num('h'),r=num('r'),o1=num('o1'),o2=num('o2'),a=h*r,b=h*1.5*o1,c=h*2*o2,t=a+b+c,hrs=r+o1+o2,avg=hrs?t/hrs:0;
 return big('Weekly gross',gbp2(t),'Overtime '+gbp2(b+c))+kv([['Basic ('+r+' h)',gbp2(a)],['Time and a half ('+o1+' h at '+gbp2(h*1.5)+')',gbp2(b)],['Double time ('+o2+' h at '+gbp2(h*2)+')',gbp2(c)],['Total hours',String(hrs)],['Average per hour worked',gbp2(avg)],['Monthly (×52/12)',gbp(t*52/12,0)],['Yearly (×52)',gbp(t*52,0)],['At least the 21+ National Living Wage (£12.71)?',avg>=12.71?'Yes':'No — check your pay','t']])+(hrs>48?'<p class="note">More than 48 hours a week on average (over 17 weeks) is only allowed if you have opted out in writing.</p>':'')+'<p class="note">Gross pay before income tax and National Insurance. Overtime is taxed like normal pay.</p>'}'''
FAQ=[
("Is overtime paid at time and a half by law in the UK?","No. UK law does not set an overtime rate, and employers don't have to pay extra for overtime at all. Time and a half (1.5×) or double time (2×) only applies if your contract, a collective agreement or a workplace policy says so. The legal floor is that your average pay for all the hours you work must not fall below the National Minimum Wage."),
("How do I calculate time and a half?","Multiply your hourly rate by 1.5, then by the overtime hours. At £14 an hour, time and a half is £21 an hour, so 6 hours of overtime pays £126. Added to 37.5 basic hours (£525) that is £651 for the week before tax."),
("How much is double time on £12.71 an hour?","£25.42 an hour. Time and a half on the April 2026 National Living Wage of £12.71 is £19.07 an hour (£19.065 rounded)."),
("Does overtime count towards holiday pay?","Regular overtime must be included in holiday pay for the first 4 weeks of statutory leave, along with other pay you normally receive. Genuinely occasional overtime does not have to be included. Your contract may give more."),
("Can my employer make me work overtime?","Only if your contract says overtime is compulsory. Even then, you cannot be made to work more than an average of 48 hours a week (usually averaged over 17 weeks) unless you have signed an opt-out, which you can cancel. Workers under 18 cannot work more than 8 hours a day or 40 hours a week."),
("Is overtime taxed more?","No. Overtime is added to your pay for the pay period and taxed through PAYE at your normal rates. A large overtime month can push some pay into a higher band for that month, but with a cumulative tax code it evens out over the tax year.")]
art='''<h2>How overtime pay works in the UK</h2>
<p>Overtime is any time you work beyond your normal contracted hours. There is <b>no statutory overtime rate</b>: your contract (or a collective agreement) decides whether overtime is paid at your normal rate, time and a half, double time, or given back as time off in lieu (TOIL). The calculator works it out as:</p>
<p><b>Weekly gross = rate × basic hours + rate × 1.5 × time-and-a-half hours + rate × 2 × double-time hours</b></p>
<h3>Common overtime multipliers at typical hourly rates</h3>
'''+table(['Hourly rate','Time and a half (1.5×)','Double time (2×)'],[['£12.71 (National Living Wage)','£19.07','£25.42'],['£14.00','£21.00','£28.00'],['£15.00','£22.50','£30.00'],['£18.00','£27.00','£36.00'],['£20.00','£30.00','£40.00'],['£25.00','£37.50','£50.00']])+'''
<h3>Worked examples (calculator results, before tax)</h3>
'''+table(['Hourly rate','Basic hours','Overtime','Weekly gross','Average per hour','Monthly (×52/12)'],[['£14.00','37.5','6 h at 1.5×','£651.00','£14.97','£2,821'],['£12.71','40','5 h at 1.5×','£603.73','£13.42','£2,616'],['£15.00','37.5','4 h at 1.5× + 4 h at 2×','£772.50','£16.98','£3,348'],['£20.00','37.5','8 h at 1.5×','£990.00','£21.76','£4,290'],['£18.00','40','8 h at 2×','£1,008.00','£21.00','£4,368']])+'''
<h3>Minimum wage rates to check against</h3>
'''+table(['Age band','From 1 April 2026','From 1 April 2027 (accepted 28 Oct 2026)'],[['21 and over (National Living Wage)','£12.71','£13.21'],['18 to 20','£10.85','£11.27'],['16 to 17','£8.00','£8.31'],['Apprentice','£8.00','£8.31']])+'''
<p class="note">Minimum wage is checked on your <b>average</b> pay over the pay reference period, including unpaid overtime. If you are paid £13 an hour for 37.5 hours (£487.50) but work 40 hours, your average is £12.19 — below the £12.71 National Living Wage for 21+.</p>
<h3>Your rights on overtime</h3>
<ul><li><b>Pay:</b> only what your contract says, but average pay for all hours worked must not fall below the minimum wage.</li><li><b>Compulsory overtime:</b> allowed if your contract says so; refusing it may be a disciplinary matter.</li><li><b>Guaranteed vs non-guaranteed:</b> if overtime is guaranteed, your employer must offer it; non-guaranteed overtime is offered as needed.</li><li><b>48-hour limit:</b> you can't be made to work more than 48 hours a week on average unless you opt out in writing; under-18s are limited to 8 hours a day and 40 a week.</li><li><b>Part-time workers:</b> are usually only paid an overtime rate once they work beyond the full-time hours, if full-timers would be.</li><li><b>Holiday pay:</b> regular overtime counts towards holiday pay for the first 4 weeks of statutory leave.</li></ul>
<h3>Tips</h3>
<ul><li>Record overtime hours yourself and compare them with your payslip — overtime is often paid a month in arrears.</li><li>If you're offered TOIL instead of pay, check how long you have to take it.</li><li>Overtime counts as income for student loan, pension contributions (if your scheme uses qualifying earnings) and Universal Credit.</li></ul>
'''+faq_html(FAQ)+'''
<p class="note">Sources (checked 22 Nov 2026): <a href="https://www.gov.uk/overtime-your-rights" rel="nofollow">GOV.UK — Overtime: your rights</a>; <a href="https://www.gov.uk/guidance/rates-and-thresholds-for-employers-2026-to-2027" rel="nofollow">HMRC — Rates and thresholds for employers 2026 to 2027</a> (minimum wage from 1 April 2026); <a href="https://www.gov.uk/government/news/lpc-recommendations-take-the-national-living-wage-to-1321" rel="nofollow">GOV.UK — LPC recommendations take the National Living Wage to £13.21</a> (rates from April 2027, accepted 28 October 2026); <a href="https://www.gov.uk/maximum-weekly-working-hours" rel="nofollow">GOV.UK — Maximum weekly working hours</a> (48-hour average, opt-out, under-18 limits). Gross pay before tax and NI.</p>'''
print(build('/uk/overtime-calculator.html','Overtime Calculator UK 2026 – Time and a Half & Double Time Pay',
 'Work out overtime pay at time and a half or double time, weekly, monthly and yearly gross, and check your average hourly pay against the 2026 £12.71 National Living Wage.',art,FAQ,calc=calc))
